INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','noun-clauses','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"noun-clauses","title":"Indirect questions, noun clauses and preparatory it","level":"B2","order":56,"summary":"Use a whole clause as a subject, object or complement, and keep embedded questions in statement order.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Clauses can fill noun-like roles","Polite indirect questions","Whether before an infinitive","Preparatory it"],"rules":[{"title":"Clauses can fill noun-like roles","explanation":"A that-clause can express the content of a belief, statement or fact. It may be the object of a verb or follow a noun or adjective. In many object clauses, that can be omitted, but it helps readers recognise a complex structure.","pattern":"I believe **that she is right**.","commonMistakes":["That does not itself supply a subject and verb; the words after it still need a complete clause."],"examples":["Choose the polite indirect question about the visitor guide. → **Could you tell me why she prepares the visitor guide?**","Choose the polite indirect question about the old portrait. → **Could you tell me why she restores the old portrait?**"],"skill":"form"},{"title":"Polite indirect questions","explanation":"An opening such as Could you tell me can make a question less direct. Inside the embedded question, use statement order. The whole sentence still takes a question mark because the outer clause is a question.","pattern":"Could you tell me **where she works**?","commonMistakes":["Where does she work is direct-question order, not the order required inside this embedded clause."],"examples":["“We have not decided **whether** to prepare the visitor guide today.”","“We have not decided **whether** to restore the old portrait today.”"],"skill":"meaning"},{"title":"Whether before an infinitive","explanation":"Use **whether to + base verb** to discuss a choice or uncertainty about an action. Whether can also introduce alternatives or follow a preposition. If is common in finite yes/no reports but does not normally replace whether before to-infinitives.","pattern":"We discussed **whether to leave**.","commonMistakes":["We discussed if to leave is not the standard pattern."],"examples":["“**It** is important to prepare the visitor guide carefully.”","“**It** is important to restore the old portrait carefully.”"],"skill":"contrast"},{"title":"Preparatory it","explanation":"English often uses **it** as a grammatical subject when a long clause or infinitive is placed later. This can make information easier to process. Compare To check is important with It is important to check. It here does not refer to an object.","pattern":"**It is important to check** the details.","commonMistakes":["Do not omit the grammatical subject in an ordinary English statement: Is important to check is incomplete."],"examples":["Complete the content clause: “We know that she **prepares** the visitor guide every week.”","Complete the content clause: “We know that she **restores** the old portrait every week.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference","dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Use a whole clause as a subject, object or complement, and keep embedded questions in statement order.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Clauses can fill noun-like roles","explanation":"A that-clause can express the content of a belief, statement or fact. It may be the object of a verb or follow a noun or adjective. In many object clauses, that can be omitted, but it helps readers recognise a complex structure.","pattern":"I believe **that she is right**.","commonMistakes":["That does not itself supply a subject and verb; the words after it still need a complete clause."],"examples":["Choose the polite indirect question about the visitor guide. → **Could you tell me why she prepares the visitor guide?**","Choose the polite indirect question about the old portrait. → **Could you tell me why she restores the old portrait?**"],"skill":"form","id":"noun-clauses-foundation-1","domain":"content-clauses","referenceIds":["bc-questions-reference","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Polite indirect questions","explanation":"An opening such as Could you tell me can make a question less direct. Inside the embedded question, use statement order. The whole sentence still takes a question mark because the outer clause is a question.","pattern":"Could you tell me **where she works**?","commonMistakes":["Where does she work is direct-question order, not the order required inside this embedded clause."],"examples":["“We have not decided **whether** to prepare the visitor guide today.”","“We have not decided **whether** to restore the old portrait today.”"],"skill":"meaning","id":"noun-clauses-foundation-2","domain":"content-clauses","referenceIds":["bc-questions-reference","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Whether before an infinitive","explanation":"Use **whether to + base verb** to discuss a choice or uncertainty about an action. Whether can also introduce alternatives or follow a preposition. If is common in finite yes/no reports but does not normally replace whether before to-infinitives.","pattern":"We discussed **whether to leave**.","commonMistakes":["We discussed if to leave is not the standard pattern."],"examples":["“**It** is important to prepare the visitor guide carefully.”","“**It** is important to restore the old portrait carefully.”"],"skill":"contrast","id":"noun-clauses-foundation-3","domain":"content-clauses","referenceIds":["bc-questions-reference","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Preparatory it","explanation":"English often uses **it** as a grammatical subject when a long clause or infinitive is placed later. This can make information easier to process. Compare To check is important with It is important to check. It here does not refer to an object.","pattern":"**It is important to check** the details.","commonMistakes":["Do not omit the grammatical subject in an ordinary English statement: Is important to check is incomplete."],"examples":["Complete the content clause: “We know that she **prepares** the visitor guide every week.”","Complete the content clause: “We know that she **restores** the old portrait every week.”"],"skill":"application","id":"noun-clauses-foundation-4","domain":"content-clauses","referenceIds":["bc-questions-reference","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"domain":"content-clauses","id":"content-clause-functions","title":"Content clauses as subjects, complements and explanations","explanation":"A content clause expresses a proposition or question and can fill several grammatical roles. It can follow a verb, noun or adjective, or function as a subject. A that-clause after a noun supplies content, while a relative clause usually identifies or describes the noun through a gap.","pattern":"the claim **that she resigned**","examples":["**That he apologised** matters.","We are certain **that the figures are correct**."],"commonMistakes":["The claim that she made has a relative gap after made; the claim that she resigned gives the content of the claim. Similar openings can hide different structures."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"content-clauses","id":"embedded-if-whether","title":"Whether, if and embedded alternatives","explanation":"Whether and if can introduce embedded yes/no questions after many verbs. Whether is generally required before a to-infinitive and preferred or required in some fronted clauses, after prepositions and with explicit alternatives. Embedded questions use statement order; subject questions already have their question word as subject.","pattern":"I wonder **whether she agrees**.","examples":["We discussed **whether to postpone** it.","It depends **on whether they agree**."],"commonMistakes":["If also introduces conditions. I’ll ask if she comes can be ambiguous between asking whether she comes and asking only on the condition that she comes."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"content-clauses","id":"extraposition-object-it","title":"Anticipatory subjects and objects with it","explanation":"English often puts a long subject clause later and uses it in the initial subject position. Certain verbs also allow anticipatory object it before an adjective or noun complement. This arrangement keeps a heavy clause near the end and gives the reader an easier starting point. Only verbs licensing the pattern allow it.","pattern":"**It** is clear **that she agrees**.","examples":["I find **it difficult to concentrate**.","We made **it clear that we would not pay**."],"commonMistakes":["Do not insert it before every clause object: I know that she agrees is ordinary; I know it that she agrees is not the same standard pattern."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["I believe **that she is right**.","Could you tell me **where she works**?","We discussed **whether to leave**.","**It is important to check** the details."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["phrasal-verbs"],"readingReferenceIds":["bc-questions-reference","dfe-grammar","cambridge-comprehensive-scope"]}'::jsonb F